/**
 * treeProvider.ts
 * 侧边栏文件树 — 使用 vscode.workspace.fs 实现 Remote Dev 兼容
 */

import * as vscode from 'vscode';
import { SyncEngine } from './syncEngine';
import { StateManager } from './core/stateManager';
import { CONSTANTS } from './utils/constants';
import { SyncFileDecorationProvider } from './ui/syncFileDecorationProvider';
import { SyncNodeStatus } from './types';

export class SyncTreeProvider implements vscode.TreeDataProvider<SyncNode> {

    private _onDidChangeTreeData: vscode.EventEmitter<SyncNode | undefined | void> = new vscode.EventEmitter<SyncNode | undefined | void>();
    readonly onDidChangeTreeData: vscode.Event<SyncNode | undefined | void> = this._onDidChangeTreeData.event;

    constructor(
        private syncEngine: SyncEngine,
        private decorationProvider?: SyncFileDecorationProvider
    ) { }

    refresh(): void {
        this._onDidChangeTreeData.fire();
    }

    getTreeItem(element: SyncNode): vscode.TreeItem {
        return element;
    }

    // 格式化时间显示
    private formatTime(timestamp: number): string {
        const date = new Date(timestamp);
        const now = new Date();
        const diffMs = now.getTime() - date.getTime();
        const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

        const timeStr = date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        
        if (diffDays === 0 && date.getDate() === now.getDate()) {
            return `今天 ${timeStr}`;
        } else if (diffDays === 1 || (diffDays === 0 && date.getDate() !== now.getDate())) {
            return `昨天 ${timeStr}`;
        } else {
            return `${date.getMonth() + 1}-${date.getDate()} ${timeStr}`;
        }
    }

    async getChildren(element?: SyncNode): Promise<SyncNode[]> {
        const workspaceFolders = vscode.workspace.workspaceFolders;
        if (!workspaceFolders || workspaceFolders.length === 0) {
            return [];
        }

        const config = vscode.workspace.getConfiguration('larksync');
        const configuredDir = config.get<string>('syncDirectory');
        const syncDirName = configuredDir !== undefined ? configuredDir : CONSTANTS.DEFAULT_SYNC_DIR;
        const rootUri = syncDirName 
            ? vscode.Uri.joinPath(workspaceFolders[0].uri, syncDirName)
            : workspaceFolders[0].uri;

        // 检查同步目录是否存在
        if (!element) {
            try {
                await vscode.workspace.fs.stat(rootUri);
            } catch {
                return [new SyncNode(
                    '尚未同步 (点击开始同步)',
                    rootUri,
                    vscode.TreeItemCollapsibleState.None
                )];
            }
        }

        const targetUri = element ? element.resourceUri! : rootUri;

        // 加载状态树以获取上次同步时间
        const stateManager = new StateManager(rootUri);
        await stateManager.loadState();
        const stateMapping = stateManager.getReverseMapping();
        const TOLERANCE_MS = 2000; // 时间误差两秒

        try {
            const entries = await vscode.workspace.fs.readDirectory(targetUri);
            const nodes: SyncNode[] = [];
            const decorationEntries: Array<{ uri: vscode.Uri; status: SyncNodeStatus }> = [];

            for (const [name, fileType] of entries) {
                // 跳过隐藏文件（以 . 开头）
                if (name.startsWith('.')) continue;

                const childUri = vscode.Uri.joinPath(targetUri, name);
                const isDir = fileType === vscode.FileType.Directory;

                if (isDir) {
                    nodes.push(new SyncNode(
                        name,
                        childUri,
                        vscode.TreeItemCollapsibleState.Collapsed
                    ));
                } else {
                    // 获取相对路径 (去除前部可能因为操作系统差异导致的 \ 或 / 问题)
                    let relativePath = childUri.path.substring(rootUri.path.length);
                    // 统一为 posix 格式，去除首部斜杠
                    relativePath = relativePath.replace(/^[/\\]/, '');

                    const state = stateMapping.get(relativePath);
                    let description = '';
                    let tooltip = childUri.fsPath;
                    let nodeStatus = 0; // fallback integer type check, we import enum later wait, no we don't import enum yet... let me import it at the top of treeProvider.ts!
                    // Wait, SyncNodeStatus is defined in types so I should import it.
                    let statusBadge: SyncNodeStatus | null = null;

                    if (state) {
                        try {
                            const stats = await vscode.workspace.fs.stat(childUri);
                            const mtime = stats.mtime;
                            const isModifiedLocally = (mtime - state.lastSyncTime) > TOLERANCE_MS;
                            
                            if (isModifiedLocally) {
                                description = `本地修改: ${this.formatTime(mtime)}`;
                                statusBadge = SyncNodeStatus.LOCAL_MODIFIED;
                            } else {
                                description = `已同步: ${this.formatTime(state.lastSyncTime)}`;
                                statusBadge = SyncNodeStatus.SYNCED;
                            }
                            tooltip = `Local: ${childUri.fsPath}\nCloud ID: ${state.documentId}`;
                        } catch {
                            // File not accessible?
                        }
                    } else if (childUri.fsPath.endsWith('.md')) {
                        description = '脱机文件 (未同步)';
                        statusBadge = SyncNodeStatus.UNTRACKED;
                    }

                    if (statusBadge && this.decorationProvider) {
                        decorationEntries.push({ uri: childUri, status: statusBadge });
                    }

                    nodes.push(new SyncNode(
                        name,
                        childUri,
                        vscode.TreeItemCollapsibleState.None,
                        {
                            command: 'vscode.open',
                            title: '打开文件',
                            arguments: [childUri]
                        },
                        description,
                        tooltip
                    ));
                }
            }

            // 更新到装饰器
            if (this.decorationProvider && decorationEntries.length > 0) {
                // To avoid importing SyncNodeStatus if not available, we cast string to any for enum. We actually should fix the import.
                this.decorationProvider.setStatuses(decorationEntries);
            }

            // 排序：目录在前，然后按名称字母序
            return nodes.sort((a, b) => {
                const aIsDir = a.collapsibleState !== vscode.TreeItemCollapsibleState.None;
                const bIsDir = b.collapsibleState !== vscode.TreeItemCollapsibleState.None;
                if (aIsDir && !bIsDir) return -1;
                if (!aIsDir && bIsDir) return 1;
                return a.label!.toString().localeCompare(b.label!.toString());
            });
        } catch (e: any) {
            console.error('LarkSync Tree Error:', e);
            return [];
        }
    }
}

class SyncNode extends vscode.TreeItem {
    constructor(
        label: string,
        uri: vscode.Uri,
        collapsibleState: vscode.TreeItemCollapsibleState,
        command?: vscode.Command,
        description?: string,
        customTooltip?: string
    ) {
        super(label, collapsibleState);
        this.resourceUri = uri;
        this.tooltip = customTooltip || uri.fsPath;
        this.description = description;
        this.command = command;

        // 使用 ThemeIcon 保持与 VS Code 视觉一致
        if (collapsibleState === vscode.TreeItemCollapsibleState.None && uri.fsPath.endsWith('.md')) {
            this.iconPath = vscode.ThemeIcon.File;
        } else if (collapsibleState !== vscode.TreeItemCollapsibleState.None) {
            this.iconPath = vscode.ThemeIcon.Folder;
        }
    }
}
