import * as vscode from 'vscode';
import { SyncEngine } from './syncEngine';
import { logger } from './logger';
import { SyncTreeProvider } from './treeProvider';
import { SyncFileDecorationProvider } from './ui/syncFileDecorationProvider';
import { DashboardPanel } from './ui/dashboardPanel';
import { TokenStore } from './auth/tokenStore';
import { OAuthManager } from './auth/oauthManager';
import { feishuClient } from './api/feishuClient';
import { CONSTANTS } from './utils/constants';

let syncEngine: SyncEngine;
let statusBarItem: vscode.StatusBarItem;
let pollingTimer: NodeJS.Timeout | null = null;
let treeProvider: SyncTreeProvider;
let decorationProvider: SyncFileDecorationProvider;

export function activate(context: vscode.ExtensionContext) {
    try {
        logger.info('LarkSync extension is now active!');

        syncEngine = new SyncEngine();

        // 注册文件装饰器（A/M/D 差异状态徽标）
        decorationProvider = new SyncFileDecorationProvider();
        context.subscriptions.push(
            vscode.window.registerFileDecorationProvider(decorationProvider)
        );

        // 注册侧边栏知识树
        treeProvider = new SyncTreeProvider(syncEngine, decorationProvider);
        context.subscriptions.push(
            vscode.window.registerTreeDataProvider('larksyncSidebar', treeProvider)
        );

        // Create Status Bar Item
        statusBarItem = vscode.window.createStatusBarItem(vscode.StatusBarAlignment.Right, 100);
        statusBarItem.command = 'larksync.startSync';
        statusBarItem.text = '$(sync) LarkSync';
        statusBarItem.tooltip = 'Click to force sync Feishu Docs';
        statusBarItem.show();
        context.subscriptions.push(statusBarItem);

        // Register Fast Sync Command
        context.subscriptions.push(vscode.commands.registerCommand('larksync.startSync', async () => {
            if (syncEngine.syncActive) {
                vscode.window.showInformationMessage('LarkSync is already syncing...');
                return;
            }

            // Check for existing cache files to warn user if missing
            const workspaceFolders = vscode.workspace.workspaceFolders;
            if (workspaceFolders && workspaceFolders.length > 0) {
                const config = vscode.workspace.getConfiguration('larksync');
                const configuredDir = config.get<string>('syncDirectory');
                const syncDirName = configuredDir !== undefined ? configuredDir : CONSTANTS.DEFAULT_SYNC_DIR;
                const rootUri = syncDirName 
                    ? vscode.Uri.joinPath(workspaceFolders[0].uri, syncDirName)
                    : workspaceFolders[0].uri;
                
                const treeUri = vscode.Uri.joinPath(rootUri, CONSTANTS.TREE_CACHE_FILE_NAME);
                const stateUri = vscode.Uri.joinPath(rootUri, CONSTANTS.STATE_FILE_NAME);
                
                try {
                    await vscode.workspace.fs.stat(treeUri);
                    // 只要有了 treeUri 就说明至少曾经全量同步过（甚至只有 state 没 tree 都不行），所以以此判断即可
                } catch {
                    // Cache file missing, prompt warning
                    const choice = await vscode.window.showWarningMessage(
                        '未检测到本地同步缓存 (.larksync_tree.json)。首次完整拉取可能非常耗时，且会重新下载所有图片。如果你其实已经有之前的缓存文件备份，请点击导入，避免重复工作。是否仍要开始全新全量同步？',
                        { modal: true },
                        '导入缓存',
                        '全新全量同步'
                    );

                    if (choice === '导入缓存') {
                        vscode.commands.executeCommand('larksync.importCacheFiles');
                        return; // Abort sync, let them import
                    } else if (choice !== '全新全量同步') {
                        return; // Cancelled
                    }
                }
            }

            statusBarItem.text = '$(sync~spin) LarkSync Syncing';
            await syncEngine.startSync(false, false);
            statusBarItem.text = '$(sync) LarkSync';
        }));

        // Register Force Full Sync Command
        context.subscriptions.push(vscode.commands.registerCommand('larksync.forceSyncTree', async () => {
            if (syncEngine.syncActive) {
                vscode.window.showInformationMessage('LarkSync is already syncing...');
                return;
            }

            statusBarItem.text = '$(sync~spin) LarkSync Fetching Tree...';
            await syncEngine.startSync(false, true);
            statusBarItem.text = '$(sync) LarkSync';
        }));

        // Register Import Cache Files Command
        context.subscriptions.push(vscode.commands.registerCommand('larksync.importCacheFiles', async () => {
            const workspaceFolders = vscode.workspace.workspaceFolders;
            if (!workspaceFolders || workspaceFolders.length === 0) {
                vscode.window.showErrorMessage('LarkSync: 请先打开一个本地工作区目录。');
                return;
            }

            const config = vscode.workspace.getConfiguration('larksync');
            const configuredDir = config.get<string>('syncDirectory');
            const syncDirName = configuredDir !== undefined ? configuredDir : CONSTANTS.DEFAULT_SYNC_DIR;
            const rootUri = syncDirName 
                ? vscode.Uri.joinPath(workspaceFolders[0].uri, syncDirName)
                : workspaceFolders[0].uri;

            const selectedUris = await vscode.window.showOpenDialog({
                canSelectFiles: true,
                canSelectFolders: false,
                canSelectMany: true,
                filters: { 'JSON 缓存文件': ['json'] },
                openLabel: '选择导出的 JSON 文件'
            });

            if (selectedUris && selectedUris.length > 0) {
                try {
                    // Ensure tracking array or count
                    let importedCount = 0;
                    for (const uri of selectedUris) {
                        const filename = uri.fsPath.split(/[/\\]/).pop();
                        // Loose matching or exact matching? Exact is safer.
                        if (filename === CONSTANTS.TREE_CACHE_FILE_NAME || filename === CONSTANTS.STATE_FILE_NAME) {
                            const destUri = vscode.Uri.joinPath(rootUri, filename);
                            await vscode.workspace.fs.copy(uri, destUri, { overwrite: true });
                            importedCount++;
                        } else {
                            vscode.window.showWarningMessage(`已忽略: [${filename}], 因为名字不匹配。请选择 .larksync_tree.json 或 .larksync_state.json。`);
                        }
                    }
                    if (importedCount > 0) {
                        vscode.window.showInformationMessage(`成功导入 ${importedCount} 个缓存文件！您可以直接开始极速同步了。`);
                        if (treeProvider) treeProvider.refresh();
                    }
                } catch (err: any) {
                    vscode.window.showErrorMessage(`导入缓存文件失败: ${err.message}`);
                }
            }
        }));

        // Register Dashboard Command
        context.subscriptions.push(vscode.commands.registerCommand('larksync.openDashboard', () => {
            DashboardPanel.createOrShow(context.extensionUri, syncEngine);
        }));

        // Register Open Sync Folder Command
        context.subscriptions.push(vscode.commands.registerCommand('larksync.openSyncFolder', async () => {
            const workspaceFolders = vscode.workspace.workspaceFolders;
            if (workspaceFolders && workspaceFolders.length > 0) {
                const config = vscode.workspace.getConfiguration('larksync');
                const configuredDir = config.get<string>('syncDirectory');
                const syncDirName = configuredDir !== undefined ? configuredDir : CONSTANTS.DEFAULT_SYNC_DIR;
                const targetUri = syncDirName 
                    ? vscode.Uri.joinPath(workspaceFolders[0].uri, syncDirName)
                    : workspaceFolders[0].uri;
                
                // 确保目录存在，避免在 OS 中 reveal 时报错
                try {
                    await vscode.workspace.fs.stat(targetUri);
                } catch {
                    await vscode.workspace.fs.createDirectory(targetUri);
                }
                
                vscode.commands.executeCommand('revealFileInOS', targetUri);
            } else {
                // CTO 体验优化：如果没有打开工作区，主动弹窗要求选择文件夹，并自动挂载为 VS Code 工作区
                const result = await vscode.window.showOpenDialog({
                    canSelectFiles: false,
                    canSelectFolders: true,
                    canSelectMany: false,
                    openLabel: '选择并打开作为 LarkSync 的本地知识库'
                });
                
                if (result && result.length > 0) {
                    // false 表示在当前窗口打开，不新开窗口
                    vscode.commands.executeCommand('vscode.openFolder', result[0], false);
                }
            }
        }));

        context.subscriptions.push(vscode.commands.registerCommand('larksync.refreshSidebar', () => {
            if (treeProvider) {
                treeProvider.refresh();
            }
        }));

        // 注册 OAuth 登录/登出（独立 try-catch，不影响核心功能）
        try {
            const tokenStore = new TokenStore(context.secrets);
            const oauthManager = new OAuthManager(tokenStore);

            context.subscriptions.push(vscode.commands.registerCommand('larksync.login', async () => {
                const success = await oauthManager.login();
                if (success) {
                    const userToken = await oauthManager.getValidUserToken();
                    if (userToken) {
                        feishuClient.setUserAccessToken(userToken);
                    }
                }
            }));

            context.subscriptions.push(vscode.commands.registerCommand('larksync.logout', async () => {
                await oauthManager.logout();
                feishuClient.setUserAccessToken('');
            }));
        } catch (authErr: any) {
            logger.error(`OAuth 初始化失败（不影响核心同步）: ${authErr.message}`, authErr);
        }

        // Setup Polling
        setupPolling();

        // Re-setup polling if configuration changes
        context.subscriptions.push(vscode.workspace.onDidChangeConfiguration(e => {
            if (e.affectsConfiguration('larksync.pollingIntervalMinutes')) {
                setupPolling();
            }
        }));

        logger.info('LarkSync 所有组件注册完毕。');
    } catch (err: any) {
        const msg = `LarkSync 激活失败: ${err.message}`;
        console.error(msg, err);
        logger.error(msg, err);
        vscode.window.showErrorMessage(msg);
    }
}

function setupPolling() {
    if (pollingTimer) {
        clearInterval(pollingTimer);
        pollingTimer = null;
    }

    const config = vscode.workspace.getConfiguration('larksync');
    const intervalMinutes = config.get<number>('pollingIntervalMinutes') || 0;

    if (intervalMinutes > 0) {
        const intervalMs = intervalMinutes * 60 * 1000;
        pollingTimer = setInterval(async () => {
            if (!syncEngine.syncActive) {
                console.log('LarkSync: Background polling triggered.');
                statusBarItem.text = '$(sync~spin) LarkSync Polling';
                await syncEngine.startSync(true, false); // silent = true, forceFullTree = false
                statusBarItem.text = '$(sync) LarkSync';
            }
        }, intervalMs);
    }
}

export function deactivate() {
    if (pollingTimer) {
        clearInterval(pollingTimer);
    }
}
